(7, 'PHIẾU KHẢO SÁT', NULL, NULL, '\n<table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\n    <tr>\n               <td height=\"30\" colspan=\"2\" align=\"left\" valign=\"middle\"><strong> PHIẾU KHẢO SÁT DỊCH VỤ CHĂM SÓC CỦA SMILE ONE </strong></td>\n	</tr>\n	\n	<tr>\n               <td height=\"30\" colspan=\"2\" align=\"left\" valign=\"middle\"><strong> Cơ sở góp ý:  CƠ SỞ 2 - GIÁP NHẤT ,THANH XUÂN, HÀ NỘI </strong></td>\n	</tr>\n	  \n	  <tr>\n				   <td height=\"30\" align=\"left\" style=\"width:200px;\" valign=\"middle\">Câu 1: Mức độ th&acirc;n thiện chung của nh&acirc;n vi&ecirc;n Smile One như thế n&agrave;o?</td>\n				   <td height=\"30\" align=\"left\" valign=\"middle\"><strong>B - Thân Thiện</strong></td>\n			</tr><tr>\n				   <td height=\"30\" align=\"left\" style=\"width:200px;\" valign=\"middle\">Câu 2: Th&aacute;i độ đ&oacute;n tiếp v&agrave; giải quyết c&aacute;c thủ tục, y&ecirc;u cầu của nh&acirc;n vi&ecirc;n Lễ t&acirc;n thế n&agrave;o?</td>\n				   <td height=\"30\" align=\"left\" valign=\"middle\"><strong>B - Tốt</strong></td>\n			</tr><tr>\n				   <td height=\"30\" align=\"left\" style=\"width:200px;\" valign=\"middle\">Câu 3: <span style=\"font-size:10.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Arial&quot;,sans-serif\">Th&aacute;i độ phục vụ của nh&acirc;n vi&ecirc;n Bảo vệ thế n&agrave;o?</span></span></span></td>\n				   <td height=\"30\" align=\"left\" valign=\"middle\"><strong>B - Tốt</strong></td>\n			</tr><tr>\n				   <td height=\"30\" align=\"left\" style=\"width:200px;\" valign=\"middle\">Câu 4: <span style=\"font-size:10.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Arial&quot;,sans-serif\">Kỹ năng tư vấn của b&aacute;c sĩ v&agrave; bạn trợ l&yacute; b&aacute;c sĩ?</span></span></span></td>\n				   <td height=\"30\" align=\"left\" valign=\"middle\"><strong>B - Bình thường, cần cải thiện</strong></td>\n			</tr><tr>\n				   <td height=\"30\" align=\"left\" style=\"w